-- #187 작성 빈도 제한과 반복 링크 탐지 (ADR-0069 decision 2 #45-15, decision 4 #187 rows, decision 7;
-- ADR-0083). Generated by `drizzle-kit generate`, then hand-edited where marked: this header and the
-- tail. The snapshot is as generated. Three new tables, nothing else changed.
--
-- - write_limit_events: one row per write the owner's fixed limits count (a new post, a new comment,
--   an edit that changed something, a stored image), by the keyed hash of the writer's verified
--   number (decision 7: per person, not per account) and the time. The limits count these rows, so a
--   deleted post still counts (#45-15). Kept a day, the longest window: the worker deletes older rows.
-- - link_uses: one row per normalised link a post or a comment took (written, or put in by an edit),
--   with the writer's number hash and the time — what the two repetition rules count over 24 hours.
--   Kept a day as well.
-- - link_flags: the operators' review list — a post or a comment, the link and the rule it met, once
--   each (UNIQUE NULLS NOT DISTINCT, so the empty one of `post_id`·`comment_id` does not make every
--   row distinct). Kept. Nothing is refused or hidden by it (decision 4 #187).
--
-- Every foreign key is RESTRICT, as every reference to a post or a comment (#46, #48).
CREATE TABLE "link_flags" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"url" varchar(2048) NOT NULL,
	"reason" varchar(16) NOT NULL,
	"post_id" uuid,
	"comment_id" uuid,
	"flagged_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "link_flags_url_reason_target_unique" UNIQUE NULLS NOT DISTINCT("url","reason","post_id","comment_id"),
	CONSTRAINT "link_flags_target_check" CHECK (num_nonnulls("link_flags"."post_id", "link_flags"."comment_id") = 1),
	CONSTRAINT "link_flags_reason_check" CHECK ("link_flags"."reason" IN ('same_account', 'many_accounts'))
);
--> statement-breakpoint
CREATE TABLE "link_uses" (
	"id" bigserial PRIMARY KEY NOT NULL,
	"url" varchar(2048) NOT NULL,
	"phone_hash" varchar(64) NOT NULL,
	"post_id" uuid,
	"comment_id" uuid,
	"used_at" timestamp (3) with time zone NOT NULL,
	CONSTRAINT "link_uses_target_check" CHECK (num_nonnulls("link_uses"."post_id", "link_uses"."comment_id") = 1),
	CONSTRAINT "link_uses_phone_hash_check" CHECK ("link_uses"."phone_hash" ~ '^[0-9a-f]{64}$')
);
--> statement-breakpoint
CREATE TABLE "write_limit_events" (
	"id" bigserial PRIMARY KEY NOT NULL,
	"phone_hash" varchar(64) NOT NULL,
	"action" varchar(8) NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "write_limit_events_phone_hash_check" CHECK ("write_limit_events"."phone_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "write_limit_events_action_check" CHECK ("write_limit_events"."action" IN ('post', 'comment', 'edit', 'upload'))
);
